select * from Swiggy limit 10


--Q1Find the total revenue generated by each Restaurant.
SELECT 
    "Restaurant Name",
    SUM("Price (INR)") AS total_revenue
FROM swiggy
GROUP BY "Restaurant Name"
ORDER BY total_revenue DESC;

--Q2Find the number of orders received by each Restaurant.
SELECT
    "Restaurant Name",
    COUNT(*) AS total_orders
FROM swiggy
GROUP BY "Restaurant Name"
ORDER BY total_orders DESC;
--Q3Find the average price of dishes in each Category.
SELECT
    "Category",
    ROUND(AVG("Price (INR)")::numeric, 2) AS average_price
FROM swiggy
GROUP BY "Category"
ORDER BY average_price DESC;
--Q4Find the total revenue generated by each Category.
SELECT
    "Category",
    ROUND(SUM("Price (INR)")::numeric, 2) AS total_revenue
FROM swiggy
GROUP BY "Category"
ORDER BY total_revenue DESC;
--Q5Find the number of unique cities
SELECT COUNT(DISTINCT "City") AS unique_cities
FROM swiggy;
--Q6Find restaurants having an average rating greater than 4.5.
SELECT
    "Restaurant Name",
    ROUND(AVG("Rating")::numeric, 2) AS average_rating
FROM swiggy
GROUP BY "Restaurant Name"
HAVING AVG("Rating") > 4.5
ORDER BY average_rating DESC;
--Q7Find the top 10 highest-rated dishes.
SELECT
    "Dish Name",
    ROUND(AVG("Rating")::numeric, 2) AS average_rating
FROM swiggy
GROUP BY "Dish Name"
ORDER BY average_rating DESC
LIMIT 10;
--Q8Find the average rating by Category.
SELECT
    "Category",
    ROUND(AVG("Rating")::numeric, 2) AS average_rating
FROM swiggy
GROUP BY "Category"
ORDER BY average_rating DESC;
--Q9Find the revenue generated by year.
SELECT
    EXTRACT(YEAR FROM TO_DATE("Order Date", 'DD-MM-YYYY')) AS year,
    ROUND(SUM("Price (INR)")::numeric, 2) AS revenue
FROM swiggy
GROUP BY EXTRACT(YEAR FROM TO_DATE("Order Date", 'DD-MM-YYYY'))
ORDER BY year;
--Q10Find the average order price by month.
SELECT
    TO_CHAR(
        TO_DATE("Order Date", 'DD-MM-YYYY'),
        'YYYY-MM'
    ) AS month,
    ROUND(AVG("Price (INR)")::numeric, 2) AS average_order_price
FROM swiggy
GROUP BY
    TO_CHAR(
        TO_DATE("Order Date", 'DD-MM-YYYY'),
        'YYYY-MM'
    )
ORDER BY month;
--Q11Find the highest-revenue restaurant in each state.
WITH restaurant_revenue AS (
    SELECT
        "State",
        "Restaurant Name",
        SUM("Price (INR)"::numeric) AS revenue
    FROM swiggy
    GROUP BY "State", "Restaurant Name"
),
ranked_restaurants AS (
    SELECT
        "State",
        "Restaurant Name",
        ROUND(revenue, 2) AS revenue,
        RANK() OVER (
            PARTITION BY "State"
            ORDER BY revenue DESC
        ) AS rank
    FROM restaurant_revenue
)
SELECT
    "State",
    "Restaurant Name",
    revenue
FROM ranked_restaurants
WHERE rank = 1
ORDER BY "State";
--Q12Find the highest-rated restaurant in each city.
WITH ranked_restaurants AS (
    SELECT
        "City",
        "Restaurant Name",
        AVG("Rating"::numeric) AS avg_rating,
        RANK() OVER (
            PARTITION BY "City"
            ORDER BY AVG("Rating"::numeric) DESC
        ) AS rank
    FROM swiggy
    GROUP BY "City", "Restaurant Name"
)
SELECT
    "City",
    "Restaurant Name",
    ROUND(avg_rating, 2) AS rating
FROM ranked_restaurants
WHERE rank = 1
ORDER BY "City";
--Q13Find the top 3 restaurants by revenue in each state.
WITH restaurant_revenue AS (
    SELECT
        "State",
        "Restaurant Name",
        SUM("Price (INR)"::numeric) AS revenue
    FROM swiggy
    GROUP BY "State", "Restaurant Name"
),
ranked_restaurants AS (
    SELECT
        "State",
        "Restaurant Name",
        revenue,
        RANK() OVER (
            PARTITION BY "State"
            ORDER BY revenue DESC
        ) AS rank
    FROM restaurant_revenue
)
SELECT
    "State",
    "Restaurant Name",
    ROUND(revenue, 2) AS revenue
FROM ranked_restaurants
WHERE rank <= 3
ORDER BY "State", revenue DESC;
--Q14Find the top 5 dishes by revenue in each category.
WITH dish_revenue AS (
    SELECT
        "Category",
        "Dish Name",
        SUM("Price (INR)"::numeric) AS revenue
    FROM swiggy
    GROUP BY "Category", "Dish Name"
),
ranked_dishes AS (
    SELECT
        "Category",
        "Dish Name",
        revenue,
        RANK() OVER (
            PARTITION BY "Category"
            ORDER BY revenue DESC
        ) AS rank
    FROM dish_revenue
)
SELECT
    "Category",
    "Dish Name",
    ROUND(revenue, 2) AS revenue
FROM ranked_dishes
WHERE rank <= 5
ORDER BY "Category", revenue DESC;
--Q15Find cities whose revenue is higher than the average city revenue.
WITH city_revenue AS (
    SELECT
        "City",
        SUM("Price (INR)"::numeric) AS revenue
    FROM swiggy
    GROUP BY "City"
)
SELECT
    "City",
    ROUND(revenue, 2) AS revenue
FROM city_revenue
WHERE revenue > (
    SELECT AVG(revenue)
    FROM city_revenue
)
ORDER BY revenue DESC;
--Q16Find restaurants whose revenue is above the overall average restaurant revenue.
WITH restaurant_revenue AS (
    SELECT
        "Restaurant Name",
        SUM("Price (INR)"::numeric) AS revenue
    FROM swiggy
    GROUP BY "Restaurant Name"
)
SELECT
    "Restaurant Name",
    ROUND(revenue, 2) AS revenue
FROM restaurant_revenue
WHERE revenue > (
    SELECT AVG(revenue)
    FROM restaurant_revenue
)
ORDER BY revenue DESC;
--Q17Find the percentage contribution of each state to total revenue.
SELECT
    "State",
    ROUND(
        SUM("Price (INR)"::numeric) * 100.0
        / SUM(SUM("Price (INR)"::numeric)) OVER (),
        2
    ) AS revenue_percentage
FROM swiggy
GROUP BY "State"
ORDER BY revenue_percentage DESC;
--Q18Find the percentage contribution of each category to total revenue.
SELECT
    "Category",
    ROUND(
        SUM("Price (INR)"::numeric) * 100.0
        / SUM(SUM("Price (INR)"::numeric)) OVER (),
        2
    ) AS revenue_percentage
FROM swiggy
GROUP BY "Category"
ORDER BY revenue_percentage DESC;
--Q19Find the monthly revenue growth.
WITH monthly_revenue AS (
    SELECT
        TO_CHAR(
            TO_DATE("Order Date", 'DD-MM-YYYY'),
            'YYYY-MM'
        ) AS month,
        SUM("Price (INR)"::numeric) AS revenue
    FROM swiggy
    GROUP BY
        TO_CHAR(
            TO_DATE("Order Date", 'DD-MM-YYYY'),
            'YYYY-MM'
        )
),
monthly_growth AS (
    SELECT
        month,
        revenue,
        LAG(revenue) OVER (ORDER BY month) AS previous_month_revenue
    FROM monthly_revenue
)
SELECT
    month,
    ROUND(revenue, 2) AS revenue,
    ROUND(
        ((revenue - previous_month_revenue)
        / NULLIF(previous_month_revenue, 0)) * 100,
        2
    ) AS growth_percentage
FROM monthly_growth
ORDER BY month;
--Q20Find the running total of revenue by month.
WITH monthly_revenue AS (
    SELECT
        TO_CHAR(
            TO_DATE("Order Date", 'DD-MM-YYYY'),
            'YYYY-MM'
        ) AS month,
        SUM("Price (INR)"::numeric) AS revenue
    FROM swiggy
    GROUP BY
        TO_CHAR(
            TO_DATE("Order Date", 'DD-MM-YYYY'),
            'YYYY-MM'
        )
)
SELECT
    month,
    ROUND(revenue, 2) AS monthly_revenue,
    ROUND(
        SUM(revenue) OVER (
            ORDER BY month
            ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
        ),
        2
    ) AS running_total_revenue
FROM monthly_revenue
ORDER BY month;